from pathlib import Path

path = Path("mobile/src/quran/QuranV3.tsx")
text = path.read_text()


def replace_once(old: str, new: str, label: str):
    global text
    if old not in text:
        raise SystemExit(f"Missing patch target: {label}")
    text = text.replace(old, new, 1)

replace_once(
    'import AsyncStorage from "@react-native-async-storage/async-storage";\n',
    'import AsyncStorage from "@react-native-async-storage/async-storage";\nimport * as Clipboard from "expo-clipboard";\n',
    "clipboard import",
)

replace_once(
    '  BackHandler,\n  FlatList,',
    '  Alert,\n  BackHandler,\n  FlatList,',
    "Alert import",
)

replace_once(
    '  const [playerVisible, setPlayerVisible] = useState(true);\n  const [loaded, setLoaded] = useState(false);',
    '  const [playerVisible, setPlayerVisible] = useState(true);\n  const [copiedSelection, setCopiedSelection] = useState(false);\n  const [loaded, setLoaded] = useState(false);',
    "copied state",
)

replace_once(
    '  const playerSurah = playerAyah ? getSurah(playerAyah.surah) : undefined;\n  const autoSpread = width >= 700;',
    '  const playerSurah = playerAyah ? getSurah(playerAyah.surah) : undefined;\n  const selectedIsActive = Boolean(selectedAyah && activeAyah && selectedAyah.surah === activeAyah.surah && selectedAyah.ayah === activeAyah.ayah);\n  const selectedIsPlaying = selectedIsActive && audioStatus.state === "playing";\n  const selectedIsPaused = selectedIsActive && audioStatus.state === "paused";\n  const selectedIsLooping = selectedIsActive && repeatQueue && audioQueue.length === 1;\n  const autoSpread = width >= 700;',
    "selected audio state",
)

replace_once(
    '  const playAyah = (ayah: QuranAyah, repeat = false) => playQueue([ayah], repeat);\n  const playSurah = (surah: number, repeat = false) => playQueue(getSurahAyahs(surah), repeat);\n\n  const togglePlayerPlayback = () => {',
    '''  const playAyah = (ayah: QuranAyah, repeat = false) => playQueue([ayah], repeat);\n  const playSurah = (surah: number, repeat = false) => playQueue(getSurahAyahs(surah), repeat);\n\n  const toggleSelectedPlayback = (ayah: QuranAyah) => {\n    const sameAyah = activeAyah?.surah === ayah.surah && activeAyah?.ayah === ayah.ayah;\n    if (!sameAyah) {\n      playAyah(ayah, false);\n      return;\n    }\n    if (audioStatus.state === "playing") QuranAudio?.pause();\n    else if (audioStatus.state === "paused") QuranAudio?.resume();\n    else playAyah(ayah, repeatQueue);\n  };\n\n  const stopSelectedPlayback = () => {\n    QuranAudio?.stop();\n    setAudioQueue([]);\n    setAudioIndex(-1);\n    setRepeatQueue(false);\n    completionRef.current = null;\n  };\n\n  const replaySelected = (ayah: QuranAyah) => {\n    playAyah(ayah, false);\n  };\n\n  const toggleSelectedLoop = (ayah: QuranAyah) => {\n    const sameAyah = activeAyah?.surah === ayah.surah && activeAyah?.ayah === ayah.ayah && audioQueue.length === 1;\n    if (!sameAyah) {\n      playAyah(ayah, true);\n      return;\n    }\n    setRepeatQueue((current) => !current);\n    if (audioStatus.state === "completed" || audioStatus.state === "idle") playAyah(ayah, !repeatQueue);\n  };\n\n  const copySelectedText = async (ayah: QuranAyah) => {\n    await Clipboard.setStringAsync(ayah.text);\n    setCopiedSelection(true);\n    setTimeout(() => setCopiedSelection(false), 1400);\n  };\n\n  const translateSelectedText = async (ayah: QuranAyah) => {\n    try {\n      const response = await fetch(`https://api.alquran.cloud/v1/ayah/${ayah.surah}:${ayah.ayah}/en.sahih`);\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      const payload = await response.json() as { data?: { text?: string } };\n      const translation = payload.data?.text?.trim();\n      if (!translation) throw new Error("No translation returned");\n      const surahName = getSurah(ayah.surah)?.nameTransliterated ?? `Surah ${ayah.surah}`;\n      Alert.alert(`${surahName} • Ayah ${ayah.ayah}`, translation);\n    } catch {\n      Alert.alert(tr("Translation unavailable", "الترجمة غير متاحة"), tr("Please check your internet connection and try again.", "تحقق من اتصال الإنترنت وحاول مرة أخرى."));\n    }\n  };\n\n  const togglePlayerPlayback = () => {''',
    "selected audio helpers",
)

old_actions = '''      {selectedAyah ? <View style={styles.ayahActions}><Text style={styles.actionRef}>{ar ? getSurah(selectedAyah.surah)?.nameArabic : getSurah(selectedAyah.surah)?.nameTransliterated} • {tr("Ayah", "الآية")} {num(selectedAyah.ayah)}</Text><View style={styles.actionRow}><Pressable onPress={() => playAyah(selectedAyah)} style={styles.actionButton}><Text style={styles.actionIcon}>▶️</Text><Text style={styles.actionLabel}>{tr("Play", "تشغيل")}</Text></Pressable><Pressable onPress={() => playAyah(selectedAyah, true)} style={styles.actionButton}><Text style={styles.actionIcon}>🔁</Text><Text style={styles.actionLabel}>{tr("Repeat", "تكرار")}</Text></Pressable><Pressable onPress={() => toggleBookmark(selectedAyah)} style={styles.actionButton}><Text style={styles.actionIcon}>🔖</Text><Text style={styles.actionLabel}>{tr("Save", "حفظ")}</Text></Pressable><Pressable onPress={() => startMemorizing(selectedAyah)} style={styles.actionButton}><Text style={styles.actionIcon}>📿</Text><Text style={styles.actionLabel}>{tr("Memorize", "حفظ")}</Text></Pressable></View></View> : null}'''

new_actions = '''      {selectedAyah ? (\n        <View style={styles.ayahActions}>\n          <View style={styles.actionHeader}>\n            <View style={styles.actionDot} />\n            <Text style={styles.actionRef} numberOfLines={1}>{ar ? getSurah(selectedAyah.surah)?.nameArabic : getSurah(selectedAyah.surah)?.nameTransliterated} • {tr("Ayah", "الآية")} {num(selectedAyah.ayah)}</Text>\n            <Pressable onPress={() => setSelectedAyah(null)} style={styles.actionClose}><Text style={styles.actionCloseText}>×</Text></Pressable>\n          </View>\n          <View style={styles.actionTransport}>\n            <Pressable onPress={() => toggleSelectedPlayback(selectedAyah)} style={[styles.actionCircle, styles.actionCircleMain]}>\n              <Text style={styles.actionCircleMainIcon}>{selectedIsPlaying ? "Ⅱ" : "▶"}</Text>\n              <Text style={styles.actionCircleMainLabel}>{selectedIsPlaying ? tr("Pause", "إيقاف مؤقت") : selectedIsPaused ? tr("Resume", "متابعة") : tr("Play", "تشغيل")}</Text>\n            </Pressable>\n            <Pressable disabled={!selectedIsActive} onPress={stopSelectedPlayback} style={[styles.actionCircle, !selectedIsActive && styles.actionDisabled]}>\n              <Text style={styles.actionCircleIcon}>■</Text><Text style={styles.actionCircleLabel}>{tr("Stop", "إيقاف")}</Text>\n            </Pressable>\n            <Pressable onPress={() => replaySelected(selectedAyah)} style={styles.actionCircle}>\n              <Text style={styles.actionCircleIcon}>↻</Text><Text style={styles.actionCircleLabel}>{tr("Replay", "إعادة")}</Text>\n            </Pressable>\n            <Pressable onPress={() => toggleSelectedLoop(selectedAyah)} style={[styles.actionCircle, selectedIsLooping && styles.actionCircleActive]}>\n              <Text style={styles.actionCircleIcon}>∞</Text><Text style={styles.actionCircleLabel}>{selectedIsLooping ? tr("Loop on", "تكرار مفعل") : tr("Loop", "تكرار")}</Text>\n            </Pressable>\n          </View>\n          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.actionTools}>\n            <Pressable onPress={() => translateSelectedText(selectedAyah)} style={styles.actionTool}><Text style={styles.actionToolIcon}>文</Text><Text style={styles.actionToolLabel}>{tr("Translate", "ترجمة")}</Text></Pressable>\n            <Pressable onPress={() => copySelectedText(selectedAyah)} style={[styles.actionTool, copiedSelection && styles.actionToolActive]}><Text style={styles.actionToolIcon}>⧉</Text><Text style={[styles.actionToolLabel, copiedSelection && styles.actionToolLabelActive]}>{copiedSelection ? tr("Copied", "تم النسخ") : tr("Copy", "نسخ")}</Text></Pressable>\n            <Pressable onPress={() => toggleBookmark(selectedAyah)} style={styles.actionTool}><Text style={styles.actionToolIcon}>🔖</Text><Text style={styles.actionToolLabel}>{tr("Save", "حفظ")}</Text></Pressable>\n            <Pressable onPress={() => startMemorizing(selectedAyah)} style={styles.actionTool}><Text style={styles.actionToolIcon}>◌</Text><Text style={styles.actionToolLabel}>{tr("Memorize", "حفظ")}</Text></Pressable>\n          </ScrollView>\n        </View>\n      ) : null}'''
replace_once(old_actions, new_actions, "selected action toolbar")

old_styles = '  ayahActions: { backgroundColor: "#fff", borderTopWidth: 1, borderTopColor: "#e1ddd4", padding: 8 }, actionRef: { color: "#17483c", fontSize: 8, fontWeight: "900", marginBottom: 6 }, actionRow: { flexDirection: "row", gap: 6 }, actionButton: { flex: 1, minHeight: 48, borderRadius: 13, alignItems: "center", justifyContent: "center", backgroundColor: "#f0f5f2" }, actionIcon: { fontSize: 16 }, actionLabel: { color: "#31564b", fontSize: 7, fontWeight: "900", marginTop: 2 },'
new_styles = '  ayahActions: { backgroundColor: "#103f35", borderTopLeftRadius: 22, borderTopRightRadius: 22, paddingHorizontal: 10, paddingTop: 8, paddingBottom: 9, shadowColor: "#000", shadowOpacity: .18, shadowRadius: 8, shadowOffset: { width: 0, height: -2 }, elevation: 12 }, actionHeader: { minHeight: 24, flexDirection: "row", alignItems: "center", gap: 6, paddingHorizontal: 3, marginBottom: 5 }, actionDot: { width: 6, height: 6, borderRadius: 3, backgroundColor: "#e6c76e" }, actionRef: { flex: 1, color: "#d7e7e1", fontSize: 8, fontWeight: "900" }, actionClose: { width: 24, height: 24, borderRadius: 12, backgroundColor: "rgba(255,255,255,.09)", alignItems: "center", justifyContent: "center" }, actionCloseText: { color: "#d7e7e1", fontSize: 17, lineHeight: 19, fontWeight: "700" }, actionTransport: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", gap: 6 }, actionCircle: { flex: 1, minHeight: 48, borderRadius: 15, backgroundColor: "rgba(255,255,255,.09)", alignItems: "center", justifyContent: "center", paddingHorizontal: 4 }, actionCircleMain: { backgroundColor: "#f7faf8" }, actionCircleActive: { backgroundColor: "#d8bd68" }, actionDisabled: { opacity: .32 }, actionCircleIcon: { color: "#f3f8f6", fontSize: 16, fontWeight: "900" }, actionCircleLabel: { color: "#d5e5df", fontSize: 6.5, fontWeight: "900", marginTop: 2, textAlign: "center" }, actionCircleMainIcon: { color: "#0b654f", fontSize: 17, fontWeight: "900" }, actionCircleMainLabel: { color: "#0b654f", fontSize: 6.5, fontWeight: "900", marginTop: 2, textAlign: "center" }, actionTools: { gap: 6, paddingTop: 7, paddingRight: 4 }, actionTool: { minWidth: 78, height: 34, borderRadius: 17, paddingHorizontal: 10, backgroundColor: "rgba(255,255,255,.08)", flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 5 }, actionToolActive: { backgroundColor: "#e4cf8b" }, actionToolIcon: { color: "#f4f8f6", fontSize: 12, fontWeight: "900" }, actionToolLabel: { color: "#d8e7e2", fontSize: 7, fontWeight: "900" }, actionToolLabelActive: { color: "#173f35" },'
replace_once(old_styles, new_styles, "selected action styles")

path.write_text(text)
print("Selected Quran toolbar patch applied")
